package com.shopsphere;
import java.time.Duration;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.client.JdkClientHttpRequestFactory;import org.springframework.web.client.RestClient;
@Configuration class OrderConfig{private RestClient client(String url,Duration connect,Duration read){var http=java.net.http.HttpClient.newBuilder().connectTimeout(connect).build();var factory=new JdkClientHttpRequestFactory(http);factory.setReadTimeout(read);return RestClient.builder().baseUrl(url).requestFactory(factory).requestInterceptor(CorrelationHeaders.interceptor()).build();}@Bean InventoryGateway inventory(@Value("${shopsphere.inventory-service-url}")String url,@Value("${shopsphere.http.connect-timeout:2s}")Duration connect,@Value("${shopsphere.http.read-timeout:3s}")Duration read){return new HttpInventoryGateway(client(url,connect,read));}@Bean ProductPricingGateway pricing(@Value("${shopsphere.product-service-url}")String url,@Value("${shopsphere.http.connect-timeout:2s}")Duration connect,@Value("${shopsphere.http.read-timeout:3s}")Duration read){return new HttpProductPricingGateway(client(url,connect,read));}}
